def transform(grid):
    """Compare aligned fields separated by a uniform divider.

    Their sole shared palette color is the base color; mark cells where both
    panels contain that shared color with 3.
    """
    h, w = len(grid), len(grid[0])
    splits = []
    for r in range(h):
        if len(set(grid[r])) == 1 and h == 2 * r + 1:
            splits.append(("h", r))
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid) and w == 2 * c + 1:
            splits.append(("v", c))
    if len(splits) != 1:
        raise ValueError("expected one centered uniform divider")
    orient, cut = splits[0]
    if orient == "h":
        a, b = grid[:cut], grid[cut + 1:]
    else:
        a = [row[:cut] for row in grid]
        b = [row[cut + 1:] for row in grid]
    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    # Dividers can differ per panel, but the intended base is the only
    # non-divider cell color shared across panel interiors on the demos. Some
    # layouts have common scaffold colors as well; choose the shared color that
    # dominates both panels jointly (background of the noisy patterned field).
    counts = {color: sum(v == color for row in a + b for v in row) for color in shared}
    base = max(counts, key=counts.get)
    return [[3 if a[r][c] == base and b[r][c] == base else base
             for c in range(len(a[0]))] for r in range(len(a))]


